    # Simulate a knowledge system with ownership-based allocation.
    # Domains have stable vocabularies (primitives) and cross-lineage references.
    domains = ['A', 'B', 'C']
    # Each domain owns a set of primitives (stable vocabulary maintained by ownership)
    owned_primitives = {
        'A': {'a1', 'a2', 'a3'},
        'B': {'b1', 'b2', 'b3'},
        'C': {'c1', 'c2', 'c3'}
    }
    # Artifacts produced in the run; some cite primitives from non-owning lineages
    artifacts = [
        {'owner': 'A', 'cites': ['a1', 'b2']},  # cross-lineage reference A->B
        {'owner': 'B', 'cites': ['b1', 'c3']},  # cross-lineage reference B->C
        {'owner': 'C', 'cites': ['c1']},        # no cross-lineage reference
        {'owner': 'A', 'cites': ['a2', 'a3']},  # no cross-lineage reference
    ]
