def check():
    # Model a circular pizza cut by 4 distinct straight lines through the center.
    # We sample points on the pizza and count connected components of the
    # complement of the cuts. Distinct angles => 8 sectors.
    import math
    n = 4
    angles = [k * math.pi / n for k in range(n)]  # distinct, evenly spaced
    # directions of the 4 lines
    dirs = [(math.cos(a), math.sin(a)) for a in angles]
    # sample points on a fine grid inside the unit disk, excluding points on any cut
    pts = []
    step = 0.01
    i = -100
    while i <= 100:
        j = -100
        x = i * step
        while j <= 100:
            y = j * step
            if x * x + y * y <= 1.0:
                on_cut = false
                for dx, dy in dirs:
                    # cross product with direction; zero means on the line
                    if abs(x * dy - y * dx) < 1e-9:
                        on_cut = true
                        break
                if not on_cut:
                    pts.append((x, y))
            j += 1
        i += 1
    # union-find to count connected components among sampled points
    parent = {p: p for p in pts}
    def find(p):
        while parent[p] != p:
            parent[p] = parent[parent[p]]
            p = parent[p]
        return p
    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb
    # connect neighboring sample points (4-neighborhood)
    pset = set(pts)
    for (x, y) in pts:
        for (dx, dy) in [(step, 0), (0, step)]:
            nb = (round(x + dx, 6), round(y + dy, 6))
            if nb in pset:
                union((x, y), nb)
    comps = len({find(p) for p in pts})
    return comps

