def check():
    # Model the pizza as the unit disk and count the number of connected components
    # after 4 concurrent straight cuts through the center.
    # We sample a grid of points in the disk and build a graph where two adjacent
    # points are connected iff the segment between them does not cross any cut line.
    import math

    n_cuts = 4
    # Cut lines through center at angles k*pi/n_cuts
    # Represent each line by a normal vector (a,b) such that a*x+b*y=0
    lines = []
    for k in range(n_cuts):
        theta = k * math.pi / n_cuts
        # normal vector (cos(theta), sin(theta))
        lines.append((math.cos(theta), math.sin(theta)))

    def crosses(p1, p2):
        x1, y1 = p1
        x2, y2 = p2
        for a, b in lines:
            v1 = a * x1 + b * y1
            v2 = a * x2 + b * y2
            # If endpoints are on opposite sides of the line, the segment crosses it
            if v1 * v2 < 0:
                return True
        return False

    N = 60
    pts = []
    idx = {}
    for i in range(N + 1):
        for j in range(N + 1):
            x = -1.0 + 2.0 * i / N
            y = -1.0 + 2.0 * j / N
            if x * x + y * y <= 1.0:
                idx[(i, j)] = len(pts)
                pts.append((x, y))

    # Union-find
    parent = list(range(len(pts)))
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx != ry:
            parent[rx] = ry

    for i in range(N + 1):
        for j in range(N + 1):
            if (i, j) not in idx:
                continue
            for di, dj in [(1, 0), (0, 1)]:
                ni, nj = i + di, j + dj
                if (ni, nj) in idx:
                    p1 = pts[idx[(i, j)]]
                    p2 = pts[idx[(ni, nj)]]
                    if not crosses(p1, p2):
                        union(idx[(i, j)], idx[(ni, nj)])

    comps = set(find(x) for x in range(len(pts)))
    return len(comps)

