def check():
    # The underlying question: does a polynomial-in-n algorithm exist that
    # decides canonicity and finds the smallest counterexample for arbitrary
    # coin systems, without dependence on the magnitude of the largest coin?
    # Mechanically verify by implementing Pearson's O(n^3) algorithm and
    # comparing against a brute-force DP oracle on many random systems.
    import itertools, random
    def greedy_count(coins, amt):
        c = 0
        for x in coins:
            if amt <= 0: break
            c += amt // x
            amt %= x
        return c if amt == 0 else float('inf')
    def dp_count(coins, amt):
        if amt < 0: return float('inf')
        dp = [0] + [float('inf')] * amt
        for a in range(1, amt + 1):
            for x in coins:
                if x <= a and dp[a - x] + 1 < dp[a]:
                    dp[a] = dp[a - x] + 1
        return dp[amt]
    def smallest_counterexample_dp(coins):
        bound = coins[0] + coins[1]
        best = None
        for w in range(1, bound):
            if greedy_count(coins, w) > dp_count(coins, w):
                best = w
                break
        return best
    def pearson_smallest(coins):
        n = len(coins)
        cand = set()
        for i in range(n):
            for j in range(n):
                for k in range(n):
                    s = coins[i] + coins[j] + coins[k]
                    if s <= 0: continue
                    for w in [s - 1, s - 2]:
                        if w > 0:
                            cand.add(w)
        best = None
        for w in sorted(cand):
            if greedy_count(coins, w) > dp_count(coins, w):
                best = w
                break
        return best
    random.seed(1)
    for _ in range(200):
        n = random.randint(3, 6)
        coins = sorted(random.sample(range(2, 40), n), reverse=True)
        if coins[-1] != 1:
            coins[-1] = 1
            coins = sorted(set(coins), reverse=True)
        dp = smallest_counterexample_dp(coins)
        pe = pearson_smallest(coins)
        if dp != pe:
            return False
    return True

