def check():
    import itertools
    def flatten_rank(n, p):
        T = {}
        for i in range(n):
            for j in range(n):
                for l in range(n):
                    for m in range(n):
                        for q in range(n):
                            for r in range(n):
                                T[(i,j,l,m,q,r)] = 1 if (j==l and m==q and r==i) else 0
        best = 0
        for mode in range(3):
            rows = {}
            for (i,j,l,m,q,r), val in T.items():
                if mode == 0:
                    key = (i,j,l,m)
                elif mode == 1:
                    key = (i,j,q,r)
                else:
                    key = (l,m,q,r)
                rows.setdefault(key, [0]*n**2)
                col = (q*r + l*n + m) if mode==0 else (l*m + q*n + r) if mode==1 else (i*j + q*n + r)
                rows[key][col] = (rows[key][col] + val) % p
            mat = [v for v in rows.values()]
            rank = 0
            for c in range(n**2):
                piv = -1
                for r in range(rank, len(mat)):
                    if mat[r][c] != 0:
                        piv = r
                        break
                if piv == -1:
                    continue
                mat[rank], mat[piv] = mat[piv], mat[rank]
                inv = pow(mat[rank][c], p-2, p)
                mat[rank] = [(x*inv)%p for x in mat[rank]]
                for r in range(len(mat)):
                    if r != rank and mat[r][c] != 0:
                        mat[r] = [(mat[r][k] - mat[r][c]*mat[rank][k])%p for k in range(n**2)]
                rank += 1
            best = max(best, rank)
        return best
    return flatten_rank(3, 2) > 22

